// Database URL encoding and the boot-time consistency guard (Phase 9, D-12, D-13, AIDA-35).
//
// docker-compose.yml builds the DATABASE_URL of migrate, app and worker from POSTGRES_USER,
// POSTGRES_PASSWORD and POSTGRES_DB. Interpolated raw, a password containing a URL-reserved
// character (`/ @ : # ?`) produces a URL that does not parse, or parses to a different password,
// and the services fail to connect with an error that says nothing about the cause. The operator
// fix is AIDA_DATABASE_URL, generated by scripts/database-url.sh with every component
// percent-encoded (D-12(1), D-12(5)). This module is the TypeScript side of the same encoding and
// the guard that refuses to boot when the URL and the POSTGRES_* values compose passed as
// AIDA_EXPECT_DB_* disagree (D-12(4)).
//
// No error, return value or log line here ever contains a value: only the name of the component
// that differs (D-13). No project imports: loaded first by instrumentation, by the worker bundle
// and by scripts/check-database-url.ts.

/** RFC 3986 unreserved characters, the only bytes left unencoded. */
const UNRESERVED = /^[A-Za-z0-9\-._~]$/;

/** Percent-encodes every UTF-8 byte outside the RFC 3986 unreserved set, with uppercase hex. */
export function encodeUrlComponent(value: string): string {
  let out = "";
  for (const byte of Buffer.from(value, "utf8")) {
    const char = String.fromCharCode(byte);
    out +=
      byte < 0x80 && UNRESERVED.test(char)
        ? char
        : `%${byte.toString(16).toUpperCase().padStart(2, "0")}`;
  }
  return out;
}

export type DatabaseUrlParts = {
  user: string;
  password: string;
  database: string;
  host: string;
  port: number;
};

/** postgresql://<user>:<password>@<host>:<port>/<database>, each of user, password, database encoded. */
export function encodeDatabaseUrl(parts: DatabaseUrlParts): string {
  return `postgresql://${encodeUrlComponent(parts.user)}:${encodeUrlComponent(parts.password)}@${parts.host}:${parts.port}/${encodeUrlComponent(parts.database)}`;
}

/**
 * The decoded components of a `postgresql:` or `postgres:` URL, or null when the string does not
 * parse as one (including malformed percent-escapes). The port defaults to 5432.
 */
export function parseDatabaseUrl(url: string): DatabaseUrlParts | null {
  let parsed: URL;
  try {
    parsed = new URL(url);
  } catch {
    return null;
  }
  if (parsed.protocol !== "postgresql:" && parsed.protocol !== "postgres:") return null;
  if (!parsed.hostname) return null;
  try {
    return {
      user: decodeURIComponent(parsed.username),
      password: decodeURIComponent(parsed.password),
      database: decodeURIComponent(parsed.pathname.replace(/^\//, "")),
      host: parsed.hostname,
      port: parsed.port ? Number(parsed.port) : 5432,
    };
  } catch {
    return null;
  }
}

export type DatabaseUrlComponent = "url" | "user" | "password" | "database";

export type DatabaseUrlCheck = { ok: true } | { ok: false; component: DatabaseUrlComponent };

type Env = Record<string, string | undefined>;

const nonEmpty = (value: string | undefined): value is string =>
  value !== undefined && value !== "";

/**
 * Compares the decoded DATABASE_URL with the AIDA_EXPECT_DB_* values compose sets on migrate, app
 * and worker. Active only when both DATABASE_URL and AIDA_EXPECT_DB_PASSWORD are non-empty, so
 * `next dev`, the E2E server and the tests, which never receive AIDA_EXPECT_*, are unaffected.
 * User and database are compared only when their expected value is non-empty. Checked in the
 * fixed order url, user, password, database; equality is exact (byte equality of the decoded
 * UTF-8 strings), with no trimming.
 */
export function checkDatabaseUrlConsistency(env: Env): DatabaseUrlCheck {
  const url = env.DATABASE_URL;
  const expectedPassword = env.AIDA_EXPECT_DB_PASSWORD;
  if (!nonEmpty(url) || !nonEmpty(expectedPassword)) return { ok: true };

  const parts = parseDatabaseUrl(url);
  if (!parts) return { ok: false, component: "url" };
  if (nonEmpty(env.AIDA_EXPECT_DB_USER) && parts.user !== env.AIDA_EXPECT_DB_USER) {
    return { ok: false, component: "user" };
  }
  if (parts.password !== expectedPassword) return { ok: false, component: "password" };
  if (nonEmpty(env.AIDA_EXPECT_DB_NAME) && parts.database !== env.AIDA_EXPECT_DB_NAME) {
    return { ok: false, component: "database" };
  }
  return { ok: true };
}

const FIX = "set AIDA_DATABASE_URL with scripts/database-url.sh";

/** Fixed per component; never contains a value. */
const MESSAGES: Record<DatabaseUrlComponent, string> = {
  url: `DATABASE_URL could not be parsed; ${FIX}`,
  user: `DATABASE_URL user does not match POSTGRES_USER; ${FIX}`,
  password: `DATABASE_URL password does not match POSTGRES_PASSWORD; ${FIX}`,
  database: `DATABASE_URL database does not match POSTGRES_DB; ${FIX}`,
};

export class DatabaseUrlMismatchError extends Error {
  readonly component: DatabaseUrlComponent;

  constructor(component: DatabaseUrlComponent) {
    super(MESSAGES[component]);
    this.name = "DatabaseUrlMismatchError";
    this.component = component;
  }
}

/** Throws DatabaseUrlMismatchError when checkDatabaseUrlConsistency reports a mismatch. */
export function assertDatabaseUrlConsistent(env: Env): void {
  const result = checkDatabaseUrlConsistency(env);
  if (!result.ok) throw new DatabaseUrlMismatchError(result.component);
}
